import { build } from 'esbuild'
import fg from 'fast-glob'
import fs from 'fs'
// biome-ignore lint/style/noRestrictedImports: TODO: can we replace with our path module?
import path from 'path'
import prettier from 'prettier'
import Handlebars from 'handlebars'

const TEMPLATES_ROOT = 'src/project-factory/templates/'

// Create virtual module content
const templateFiles = fg.sync(
    [
        `${TEMPLATES_ROOT}*/**/*`,
        `!${TEMPLATES_ROOT}*/**/.DS_Store`,
        `!${TEMPLATES_ROOT}templates.d.ts.hbs`,
        `!${TEMPLATES_ROOT}*/**/.template-description.json`,
    ],
    { dot: true }
)
console.log(
    `Bundling templates:\n${templateFiles.map((file) => `\t - ${path.relative(process.cwd(), file)}`).join('\n')}`
)

interface TemplateFile {
    path: string
    content: string
}

export interface TemplateParam {
    label: string
    default?: string
}

interface TemplateInfo {
    name?: string
    description?: string
    partial?: boolean
    params?: Record<string, TemplateParam>
    [key: string]: unknown
}

interface TemplateLeaf {
    info: TemplateInfo
    files: TemplateFile[]
}

// The nested type: each property is either another nested object or an array of templates
interface NestedTemplates {
    [key: string]: NestedTemplates | TemplateLeaf
}

// Flat collection: key => TemplateLeaf
const templatesObj: {
    templates: { [key: string]: TemplateLeaf }
} = {
    templates: {},
}

function ensureLeafFlat(
    container: { [key: string]: TemplateLeaf },
    key: string,
    infoProvider: () => TemplateInfo
): TemplateLeaf {
    const current = container[key] as TemplateLeaf | undefined
    if (!current || Array.isArray(current as unknown) || !(current as TemplateLeaf).files) {
        container[key] = { info: infoProvider(), files: [] }
    }
    return container[key] as TemplateLeaf
}

templateFiles.forEach((file) => {
    let templateRoot = file
    let descriptionPath = ''
    while (!descriptionPath && templateRoot !== '.') {
        templateRoot = path.dirname(templateRoot)
        const testPath = path.join(templateRoot, '.template-description.json')
        if (fs.existsSync(testPath)) {
            descriptionPath = testPath
        }
    }
    const relative = path.relative(TEMPLATES_ROOT, templateRoot).replace(/\\/g, '/')
    const segments = relative.split('/')
    const relativePathAfterRoot = path.relative(templateRoot, file).replace(/\.hbs$/, '')
    const templateKey = segments.length ? segments.join('.') : '_'

    const leaf = ensureLeafFlat(templatesObj.templates, templateKey, () => {
        if (fs.existsSync(descriptionPath)) {
            try {
                return JSON.parse(fs.readFileSync(descriptionPath, 'utf8')) as TemplateInfo
            } catch (err) {
                console.warn(`Failed to parse template description at ${descriptionPath}:`, err)
            }
        }
        return {}
    })

    const raw = fs.readFileSync(file, 'utf8')
    leaf.files.push({ path: relativePathAfterRoot, content: raw })
})

// Write/update TypeScript declaration file for IDE support
const typeDefTemplatePath = path.join('src', 'project-factory', 'templates', 'templates.d.ts.hbs')
const typeDefDistPath = path.join('dist', 'project-factory', 'templates.d.ts')
function buildTypeLiteral(obj: NestedTemplates, indent = 0): string {
    return Object.entries(obj)
        .map(([key, val]) => {
            const safeKey = /^[a-zA-Z_$][a-zA-Z0-9_$]*$/.test(key) ? key : `'${key}'`
            if (!Array.isArray(val) && (val as TemplateLeaf).files) {
                return `${safeKey}: TemplateLeaf;`
            }
            return `${safeKey}: {\n${buildTypeLiteral(val as NestedTemplates, indent + 1)}\n};`
        })
        .join('\n')
}

const typeLiteral = buildTypeLiteral(templatesObj.templates as NestedTemplates)
const typeDefTemplate = Handlebars.compile(fs.readFileSync(typeDefTemplatePath, { encoding: 'utf8' }))
const typeDefDistDir = path.dirname(typeDefDistPath)
if (!fs.existsSync(typeDefDistDir)) {
    fs.mkdirSync(typeDefDistDir, { recursive: true })
}

prettier
    .format(typeDefTemplate({ REPLACE_WITH_TEMPLATES_AT_BUILD_TIME: typeLiteral }), {
        parser: 'typescript',
        semi: false,
        singleQuote: true,
        trailingComma: 'es5',
        tabWidth: 4,
    })
    .then((formatted) => {
        fs.writeFileSync(typeDefDistPath, formatted)
        console.log(`Updated type definitions at ${typeDefDistPath}`)
    })

const virtualModuleId = 'virtual:templates'
const virtualSource = `const data = ${JSON.stringify(templatesObj, null, 4)};\nmodule.exports = data;`

// Custom plugin to define the virtual module
const virtualTemplatesPlugin = {
    name: 'virtual-templates',
    setup(build) {
        build.onResolve({ filter: new RegExp(`^${virtualModuleId}$`) }, () => ({
            path: virtualModuleId,
            namespace: 'virtual',
        }))

        build.onLoad({ filter: /.*/, namespace: 'virtual' }, () => ({
            contents: virtualSource,
            loader: 'ts',
        }))
    },
}

// Run esbuild
build({
    entryPoints: [`${TEMPLATES_ROOT}index.js`],
    bundle: true,
    outfile: 'dist/project-factory/templates.js',
    format: 'cjs',
    plugins: [virtualTemplatesPlugin],
}).catch(console.error)
